<script setup lang="ts">import FiltroCodigoAutocomplete from './FiltroCodigoAutocomplete.vue';import type { EtapaEngrase,FiltroCodigoSugerencia,FiltrosEngraseQuery,TipoEquipoEngrase,TipoFiltroEngrase } from '@/stores/dbequipos/engrase/filtrosEngrase.types';defineProps<{filters:FiltrosEngraseQuery;tiposEquipo:TipoEquipoEngrase[];tiposFiltro:TipoFiltroEngrase[];etapas:EtapaEngrase[];sugerenciasCodigo:FiltroCodigoSugerencia[];loading:boolean;loadingSugerencias:boolean}>();const emit=defineEmits<{updateFilters:[Partial<FiltrosEngraseQuery>];searchCodeSuggestions:[string];selectCodeSuggestion:[FiltroCodigoSugerencia];clearCode:[]}>();</script>
<template><section class="grid gap-3 rounded-lg border border-gray-200 bg-white p-3 shadow-sm lg:grid-cols-6" aria-label="Filtros de equipos"><FiltroCodigoAutocomplete class="lg:col-span-2" :model-value="filters.codigoExactoSeleccionado??''" :sugerencias="sugerenciasCodigo" :loading="loadingSugerencias" @update:model-value="emit('updateFilters',{codigoExactoSeleccionado:null})" @search="emit('searchCodeSuggestions',$event)" @select="emit('selectCodeSuggestion',$event)" @clear="emit('clearCode')"/><label class="block text-xs font-semibold text-main">Tipo de equipo<select class="mt-1 h-9 w-full rounded-md border border-gray-200 bg-white px-2 text-sm font-normal text-gray-700" :value="filters.tipoEquipoId??''" @change="emit('updateFilters',{tipoEquipoId:Number(($event.target as HTMLSelectElement).value)||null})"><option value="">Todos</option><option v-for="item in tiposEquipo" :key="item.id" :value="item.id">{{item.nombre}}</option></select></label><label class="block text-xs font-semibold text-main">Modelo<input class="mt-1 h-9 w-full rounded-md border border-gray-200 px-2 text-sm font-normal text-gray-700" :value="filters.modelo" @input="emit('updateFilters',{modelo:($event.target as HTMLInputElement).value})"></label><label class="block text-xs font-semibold text-main">Etapa<select class="mt-1 h-9 w-full rounded-md border border-gray-200 bg-white px-2 text-sm font-normal text-gray-700" :value="filters.etapaId??''" @change="emit('updateFilters',{etapaId:Number(($event.target as HTMLSelectElement).value)||null})"><option value="">Todas / Sin etapa</option><option v-for="item in etapas" :key="item.id" :value="item.id">{{item.nombre}}</option></select></label><fieldset class="border-0"><legend class="mb-1 text-xs font-semibold text-main">Estado</legend><div class="flex gap-1"><button class="h-9 flex-1 rounded-md border text-xs" :class="filters.estadoEquipo==='activo'?'border-success bg-success-bg text-success':'border-gray-200 text-gray-500'" @click="emit('updateFilters',{estadoEquipo:'activo'})">Activos</button><button class="h-9 flex-1 rounded-md border text-xs" :class="filters.estadoEquipo==='descartado'?'border-danger bg-danger-bg text-danger':'border-gray-200 text-gray-500'" @click="emit('updateFilters',{estadoEquipo:'descartado'})">Descartados</button></div></fieldset></section></template>
